import { requireRole } from "@/lib/auth/utils"
import { createServerSupabaseClient } from "@/lib/supabase/server"
import Link from "next/link"
import { redirect } from "next/navigation"
import {
  LayoutDashboard,
  User,
  Shield,
  Calendar,
  ClipboardList,
  FileText,
  MessageSquare,
  Settings,
  LogOut,
  AlertCircle,
  Briefcase
} from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { UserDropdown } from "@/components/user-dropdown"

const navItems = [
  {
    label: "Find Work",
    href: "/coach/listings",
    icon: Briefcase
  },
  {
    label: "My Applications",
    href: "/coach/applications",
    icon: FileText
  },
  {
    label: "Verification",
    href: "/coach/verify",
    icon: Shield
  },
  {
    label: "Availability",
    href: "/coach/availability",
    icon: Calendar
  }
]

export default async function CoachLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const user = await requireRole('coach')
  const supabase = await createServerSupabaseClient()

  // Get coach profile and user details to check verification status
  const { data: profile } = await supabase
    .from('coach_profiles')
    .select('*, user:users!coach_profiles_user_id_fkey(first_name, last_name)')
    .eq('user_id', user.id)
    .single()

  const isVerified = profile?.wwcc_number && profile?.insurance_url && profile?.first_aid_url

  return (
    <div className="min-h-screen flex">
      {/* Sidebar */}
      <aside className="w-64 border-r bg-muted/20">
        <div className="p-6">
          <h2 className="text-lg font-semibold mb-2">Coach Portal</h2>
          <div className="mt-3">
            {isVerified ? (
              <Badge className="bg-green-500/10 text-green-700 border-green-200">
                <Shield className="w-3 h-3 mr-1" />
                Verified
              </Badge>
            ) : (
              <Badge variant="secondary">
                <AlertCircle className="w-3 h-3 mr-1" />
                Unverified
              </Badge>
            )}
          </div>
        </div>

        <nav className="px-4 space-y-1">
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className="flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-muted/50 transition-colors"
            >
              <item.icon className="w-4 h-4 text-muted-foreground" />
              <span className="text-sm">{item.label}</span>
              {item.label === "Verification" && !isVerified && (
                <span className="ml-auto w-2 h-2 bg-orange-500 rounded-full" />
              )}
            </Link>
          ))}
        </nav>
      </aside>

      {/* Main Content */}

"use client"

import Link from "next/link"
import { usePathname, useRouter } from "next/navigation"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { 
  Menu, 
  X, 
  User, 
  ChevronDown, 
  LayoutDashboard, 
  Settings, 
  LogOut 
} from "lucide-react"
import { useState, useEffect } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { createClient } from "@/lib/supabase/client"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

interface NavItem {
  label: string
  href: string
}

const publicNavItems: NavItem[] = [
  { label: "How It Works", href: "/how-it-works" },
  { label: "Pricing", href: "/pricing" },
]

export function Navigation() {
  const pathname = usePathname()
  const router = useRouter()
  const [isScrolled, setIsScrolled] = useState(false)
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [user, setUser] = useState<any>(null)
  const [userRole, setUserRole] = useState<'coach' | 'org' | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const supabase = createClient()

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 10)
    }

    window.addEventListener("scroll", handleScroll)
    return () => window.removeEventListener("scroll", handleScroll)
  }, [])

  // Close mobile menu on route change
  useEffect(() => {
    setIsMobileMenuOpen(false)
  }, [pathname])

  // Check authentication state
  useEffect(() => {
    async function getUser() {
      const { data: { user } } = await supabase.auth.getUser()
      setUser(user)

      // Get user role from the database
      if (user) {
        const { data: userData } = await supabase
          .from('users')
          .select('role')
          .eq('id', user.id)
          .single()

        if (userData) {
          setUserRole(userData.role as 'coach' | 'org')
        }
      }

      setIsLoading(false)
    }

    getUser()

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      setUser(session?.user || null)

      // Get user role when auth state changes
      if (session?.user) {
        const { data: userData } = await supabase
          .from('users')
          .select('role')
          .eq('id', session.user.id)
          .single()

        if (userData) {
          setUserRole(userData.role as 'coach' | 'org')
        }
      } else {
        setUserRole(null)
      }

      setIsLoading(false)
    })

    return () => subscription.unsubscribe()
  }, [supabase.auth, supabase])

  const isAuthPage = pathname?.startsWith("/auth")
  const isDashboard = pathname?.includes("/dashboard")
  const isLoggedIn = !!user

  return (
    <nav className={cn(
      "fixed top-0 left-0 right-0 z-50 transition-all duration-200",
      isScrolled ? "glass shadow-soft" : "bg-transparent"
    )}>
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <Link href="/" className="flex items-center space-x-2">
            <div className="w-8 h-8 rounded-lg bg-primary flex items-center justify-center">
              <span className="text-primary-foreground font-bold text-lg">C</span>
            </div>
            <span className="text-xl font-semibold">CoachFlow</span>
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-8">
            {publicNavItems.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "text-sm font-medium transition-colors hover:text-primary",
                  pathname === item.href
                    ? "text-primary"
                    : "text-muted-foreground"
                )}
              >
                {item.label}
              </Link>
            ))}

            {!isAuthPage && !isLoading && (
              <>
                {!isLoggedIn ? (
                  <div className="flex items-center gap-2">
                    <Button variant="ghost" size="sm" asChild>
                      <Link href="/auth/sign-in">Sign In</Link>
                    </Button>
                    <Button size="sm" className="bg-primary hover:bg-primary/90" asChild>
                      <Link href="/auth/sign-up">Sign Up</Link>
                    </Button>
                  </div>
                ) : (
                  <div className="flex items-center space-x-4">
                    {isDashboard && (
                      <Badge variant="secondary" className="bg-green-500/10 text-green-700 border-green-200">
                        Free during beta
                      </Badge>
                    )}
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button 
                          variant="ghost" 
                          className="flex items-center space-x-2 hover:bg-accent"
                        >
                          <User className="w-4 h-4" />
                          <span className="text-sm font-medium">{user?.email}</span>
                          <ChevronDown className="w-4 h-4 opacity-50" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-56">
                        <DropdownMenuLabel>My Account</DropdownMenuLabel>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem 
                          onClick={() => router.push(userRole === 'coach' ? '/coach/dashboard' : '/org/dashboard')}
                          className="cursor-pointer"
                        >
                          <LayoutDashboard className="mr-2 h-4 w-4" />
                          Dashboard
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          onClick={() => router.push(userRole === 'coach' ? '/coach/profile' : '/org/settings')}
                          className="cursor-pointer"
                        >
                          <Settings className="mr-2 h-4 w-4" />
                          {userRole === 'coach' ? 'Profile' : 'Settings'}
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem 
                          className="cursor-pointer"
                          onSelect={async (e) => {
                            e.preventDefault()
                            try {
                              await supabase.auth.signOut()
                              localStorage.clear()
                              sessionStorage.clear()
                              window.location.href = '/'
                            } catch (err) {
                              console.error('Sign out error:', err)
                              window.location.href = '/'
                            }
                          }}
                        >
                          <LogOut className="mr-2 h-4 w-4" />
                          Sign Out
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                )}
              </>
            )}
          </div>

          {/* Mobile Menu Button */}
          <button
            className="md:hidden p-2"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            aria-label="Toggle mobile menu"
          >
            {isMobileMenuOpen ? (
              <X className="w-6 h-6" />
            ) : (
              <Menu className="w-6 h-6" />
            )}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="md:hidden glass border-t"
          >
            <div className="container mx-auto px-4 py-4 space-y-4">
              {publicNavItems.map((item) => (
                <Link
                  key={item.href}
                  href={item.href}
                  className={cn(
                    "block py-2 text-sm font-medium transition-colors hover:text-primary",
                    pathname === item.href
                      ? "text-primary"
                      : "text-muted-foreground"
                  )}
                >
                  {item.label}
                </Link>
              ))}

              {!isAuthPage && !isLoading && (
                <div className="space-y-2 pt-4 border-t">
                  {!isLoggedIn ? (
                    <div className="space-y-2">
                      <Button variant="ghost" className="w-full" asChild>
                        <Link href="/auth/sign-in">Sign In</Link>
                      </Button>
                      <Button className="w-full bg-primary hover:bg-primary/90" asChild>
                        <Link href="/auth/sign-up">Sign Up</Link>
                      </Button>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      {isDashboard && (
                        <Badge variant="secondary" className="bg-green-500/10 text-green-700 border-green-200 w-full justify-center">
                          Free during beta
                        </Badge>
                      )}
                      <div className="flex items-center space-x-2 px-2 py-2 bg-muted/50 rounded-md">
                        <User className="w-4 h-4" />
                        <span className="text-sm font-medium">{user?.email}</span>
                      </div>
                      <div className="space-y-1">
                        <Button
                          variant="ghost"
                          className="w-full justify-start"
                          onClick={() => {
                            router.push(userRole === 'coach' ? '/coach/dashboard' : '/org/dashboard')
                            setIsMobileMenuOpen(false)
                          }}
                        >
                          <LayoutDashboard className="mr-2 h-4 w-4" />
                          Dashboard
                        </Button>
                        <Button
                          variant="ghost"
                          className="w-full justify-start"
                          onClick={() => {
                            router.push(userRole === 'coach' ? '/coach/profile' : '/org/settings')
                            setIsMobileMenuOpen(false)
                          }}
                        >
                          <Settings className="mr-2 h-4 w-4" />
                          {userRole === 'coach' ? 'Profile' : 'Settings'}
                        </Button>
                      </div>
                      <Button
                        variant="ghost"
                        className="w-full justify-start"
                        onClick={async () => {
                          try {
                            await supabase.auth.signOut()
                            localStorage.clear()
                            sessionStorage.clear()
                            window.location.href = '/'
                          } catch (err) {
                            console.error('Sign out error:', err)
                            window.location.href = '/'
                          }
                        }}
                      >
                        <LogOut className="mr-2 h-4 w-4" />
                        Sign Out
                      </Button>
                    </div>
                  )}
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  )
}

